  let studentName = 'HỌC VIÊN XUẤT SẮC';
  let studentEmail = (cert && cert.recipient_email) || (user && user.email) || localStorage.getItem('remembered_user_email') || localStorage.getItem('user_email') || 'learner@vihtech.edu.vn';
