window.switchAdminTab = async function(tabName, btnEl) {
  document.querySelectorAll('.sub-tabs-bar .pill-tab').forEach(b => b.classList.remove('active'));
  if (btnEl) btnEl.classList.add('active');
  window.adminState.activeSubTab = tabName;
  await loadAdminSubTab(tabName);
};

window.loadAdminSubTab = async function(tabName) {
  const container = document.getElementById('admin-subtab-content-container');
  if (!container) return;
  container.innerHTML = '<div class="loading-dots" style="padding:40px; text-align:center;"><span></span><span></span><span></span></div>';

  try {
    if (tabName === 'finance') {
      await renderAdminFinanceTab(container);
    } else if (tabName === 'crm') {
      await renderAdminCrmTab(container);
    } else if (tabName === 'orders') {
      await renderAdminOrdersTab(container);
    } else if (tabName === 'vocab') {
      await renderAdminVocabTab(container);
    } else if (tabName === 'exams') {
      await renderAdminExamsTab(container);
    } else if (tabName === 'ai') {
      await renderAdminAiProfilesTab(container);
    } else if (tabName === 'audit') {
      await renderAdminAuditTab(container);
    }
  } catch (err) {
    container.innerHTML = `<div class="card" style="color:var(--accent-red); padding:20px; text-align:center;">
      ❌ Lỗi khi tải dữ liệu quản trị: ${err.message}
    </div>`;
  }
};

// ── 1. SUB-TAB DOANH THU & TÀI CHÍNH (FINANCE) ──────────────────────────────
async function renderAdminFinanceTab(container) {
  const stats = await api.admin.commercialStats();
  window.adminState.commercialStats = stats;

  const fmtVnd = (num) => new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(num || 0);

  const packagesHtml = (stats.packages_breakdown || []).map(p => `
    <tr>
      <td style="font-weight:700; color:var(--text-primary); padding:12px 14px;">${p.name}</td>
      <td style="color:#10b981; font-weight:800; padding:12px 14px;">${fmtVnd(p.price_vnd)}</td>
      <td style="font-weight:800; padding:12px 14px; text-align:center;">${p.sales_count}</td>
      <td style="padding:12px 14px; text-align:center;">
        <div style="display:flex; align-items:center; gap:8px; justify-content:center;">
          <div class="progress-bar" style="width:100px; height:8px;"><div class="progress-fill" style="width:${p.share_pct}%; background:var(--accent-primary);"></div></div>
          <span style="font-size:12px; font-weight:700;">${p.share_pct}%</span>
        </div>
      </td>
    </tr>
  `).join('');

  const chartBarsHtml = (stats.monthly_chart || []).map(m => {
    const heightPct = Math.min(100, Math.max(15, (m.revenue_vnd / 50000000) * 100));
    return `
      <div style="display:flex; flex-direction:column; align-items:center; gap:8px; flex:1;">
        <div style="font-size:11px; font-weight:800; color:#38bdf8;">${fmtVnd(m.revenue_vnd).replace('₫','').trim()}</div>
        <div style="width:100%; max-width:44px; height:160px; background:rgba(255,255,255,0.06); border-radius:8px; display:flex; align-items:flex-end; padding:3px;">
          <div style="width:100%; height:${heightPct}%; background:linear-gradient(180deg, #38bdf8, #818cf8); border-radius:6px; transition:height 0.4s ease;" title="${m.month}: ${fmtVnd(m.revenue_vnd)} (${m.orders} đơn)"></div>
        </div>
        <div style="font-size:11.5px; font-weight:700; color:var(--text-secondary);">${m.month}</div>
      </div>
    `;
  }).join('');

  container.innerHTML = `
    <!-- TOP FINANCIAL METRICS CARDS -->
    <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(220px, 1fr)); gap:16px; margin-bottom:24px;">
      <div class="card" style="padding:20px; border-left:4px solid #10b981; background:var(--bg-card); border-radius:14px;">
        <div style="font-size:12px; color:var(--text-secondary); font-weight:700; text-transform:uppercase; margin-bottom:6px;">💰 TỔNG DOANH THU LŨY KẾ</div>
        <div style="font-size:24px; font-weight:900; color:#10b981;">${fmtVnd(stats.gross_revenue_vnd)}</div>
        <div style="font-size:11.5px; color:#10b981; margin-top:4px;">▲ +24.8% so với quý trước</div>
      </div>

      <div class="card" style="padding:20px; border-left:4px solid #38bdf8; background:var(--bg-card); border-radius:14px;">
        <div style="font-size:12px; color:var(--text-secondary); font-weight:700; text-transform:uppercase; margin-bottom:6px;">📈 DOANH THU ĐỊNH KỲ (MRR)</div>
        <div style="font-size:24px; font-weight:900; color:#38bdf8;">${fmtVnd(stats.monthly_recurring_revenue_vnd)}</div>
        <div style="font-size:11.5px; color:var(--text-secondary); margin-top:4px;">Tháng 8/2026 đang ghi nhận</div>
      </div>

      <div class="card" style="padding:20px; border-left:4px solid #eab308; background:var(--bg-card); border-radius:14px;">
        <div style="font-size:12px; color:var(--text-secondary); font-weight:700; text-transform:uppercase; margin-bottom:6px;">👑 HỘI VIÊN VIP ACTIVE</div>
        <div style="font-size:24px; font-weight:900; color:#eab308;">${stats.total_subscribers} Thành Viên</div>
        <div style="font-size:11.5px; color:#eab308; margin-top:4px;">Tỷ lệ gia hạn: 88.5%</div>
      </div>

      <div class="card" style="padding:20px; border-left:4px solid #ec4899; background:var(--bg-card); border-radius:14px;">
        <div style="font-size:12px; color:var(--text-secondary); font-weight:700; text-transform:uppercase; margin-bottom:6px;">🎯 CHUYỂN ĐỔI (CONVERSION)</div>
        <div style="font-size:24px; font-weight:900; color:#ec4899;">${stats.conversion_rate_pct}%</div>
        <div style="font-size:11.5px; color:var(--text-secondary); margin-top:4px;">ARPU: ${fmtVnd(stats.average_revenue_per_user_vnd)}/User</div>
      </div>
    </div>

    <!-- REVENUE CHART & PACKAGES GRID -->
    <div style="display:grid; grid-template-columns:1.5fr 1fr; gap:20px; align-items:start; margin-bottom:24px;">
      <!-- REVENUE CHART -->
      <div class="card" style="padding:22px; background:var(--bg-card); border-radius:16px;">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:18px;">
          <div>
            <div style="font-size:15px; font-weight:900; color:var(--text-primary);">📊 BIỂU ĐỒ TĂNG TRƯỞNG DOANH THU 6 THÁNG QUA</div>
            <div style="font-size:12px; color:var(--text-secondary);">Thống kê dòng tiền đăng ký gói học viên qua các cổng thanh toán điện tử</div>
          </div>
          <span class="badge badge-green" style="font-weight:800;">TĂNG TRƯỞNG DƯƠNG</span>
        </div>

        <div style="display:flex; justify-content:space-between; align-items:flex-end; gap:12px; height:210px; padding:10px 0;">
          ${chartBarsHtml}
        </div>
      </div>

      <!-- PACKAGES BREAKDOWN TABLE -->
      <div class="card" style="padding:22px; background:var(--bg-card); border-radius:16px;">
        <div style="font-size:15px; font-weight:900; color:var(--text-primary); margin-bottom:14px;">
          📦 TỶ TRỌNG CÁC GÓI DỊCH VỤ VIP
        </div>
        <div style="overflow-x:auto;">
          <table style="width:100%; border-collapse:collapse; font-size:12.5px;">
            <thead>
              <tr style="border-bottom:2px solid var(--border); text-align:left; color:var(--text-secondary);">
                <th style="padding:8px 14px;">Tên Gói</th>
                <th style="padding:8px 14px;">Giá Niêm Yết</th>
                <th style="padding:8px 14px; text-align:center;">Số Lượng</th>
                <th style="padding:8px 14px; text-align:center;">Tỷ Trọng</th>
              </tr>
            </thead>
            <tbody>
              ${packagesHtml}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  `;
}

// ── 2. SUB-TAB QUẢN LÝ HỌC VIÊN CRM (USERS) ──────────────────────────────────
async function renderAdminCrmTab(container) {
  const users = await api.admin.users();
  window.adminState.users = users;

  const usersRowsHtml = users.map((u, idx) => `
    <tr style="border-bottom:1px solid var(--border);">
      <td style="padding:12px 10px; font-weight:700; color:var(--text-secondary);">${idx + 1}</td>
      <td style="padding:12px 10px;">
        <div style="font-weight:800; color:var(--text-primary); font-size:13.5px;">${u.full_name || u.username}</div>
        <div style="font-size:11.5px; color:var(--text-secondary);">${u.email}</div>
      </td>
      <td style="padding:12px 10px;">
        <span class="badge ${u.role === 'admin' ? 'badge-red' : u.role === 'teacher' ? 'badge-yellow' : 'badge-cyan'}" style="font-weight:800; font-size:11px; text-transform:uppercase;">
          ${u.role}
        </span>
      </td>
      <td style="padding:12px 10px; text-align:center;">
        <span class="badge badge-purple" style="font-weight:800; font-size:11px;">${u.level || 'B1'}</span>
      </td>
      <td style="padding:12px 10px; text-align:center;">
        <div style="font-size:12.5px; font-weight:800; color:#38bdf8;">⚡ ${u.xp || 0} XP</div>
        <div style="font-size:11.5px; font-weight:700; color:#facc15;">🪙 ${u.coins || 0} Xu</div>
      </td>
      <td style="padding:12px 10px; text-align:center; font-weight:800; color:#f97316;">
        🔥 ${u.streak || 0} ngày
      </td>
      <td style="padding:12px 10px; text-align:center;">
        <span class="badge ${u.is_active ? 'badge-green' : 'badge-red'}" style="font-weight:800; font-size:11px;">
          ${u.is_active ? '✅ Hoạt động' : '🔒 Đã khóa'}
        </span>
      </td>
      <td style="padding:12px 10px; text-align:right;">
        <div style="display:inline-flex; gap:6px;">
          <button class="btn btn-sm btn-ghost" onclick="openAdjustFundsModal(${u.id}, '${u.email}', ${u.coins||0}, ${u.xp||0}, ${u.streak||0})" title="Cộng / Trừ Xu & XP" style="padding:4px 8px; font-size:13px;">
            💰
          </button>
          <button class="btn btn-sm btn-ghost" onclick="openResetPasswordModal(${u.id}, '${u.email}')" title="Đặt lại mật khẩu" style="padding:4px 8px; font-size:13px;">
            🔑
          </button>
          <button class="btn btn-sm ${u.is_active ? 'btn-danger' : 'btn-success'}" onclick="toggleUserActive(${u.id})" style="padding:4px 8px; font-size:11.5px; font-weight:800;">
            ${u.is_active ? 'Khóa' : 'Mở'}
          </button>
          <button class="btn btn-sm btn-ghost" onclick="changeUserRolePrompt(${u.id}, '${u.role}')" title="Đổi vai trò" style="padding:4px 8px; font-size:13px;">
            🎭
          </button>
        </div>
      </td>
    </tr>
  `).join('');

  container.innerHTML = `
    <div class="card" style="padding:22px; background:var(--bg-card); border-radius:16px;">
      <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:14px; margin-bottom:18px;">
        <div>
          <div style="font-size:16px; font-weight:900; color:var(--text-primary);">
            👥 DANH SÁCH HỌC VIÊN & KHÁCH HÀNG CRM (${users.length} Tài Khoản)
          </div>
          <div style="font-size:12px; color:var(--text-secondary);">
            Quản lý tài khoản, điều chỉnh số dư Xu & XP, nâng cấp gói VIP Pro và bảo mật người dùng
          </div>
        </div>

        <div style="display:flex; gap:10px;">
          <input type="text" id="crm-user-search-input" class="form-control" placeholder="🔍 Tìm học viên theo tên / email..." oninput="searchCrmUsers(this.value)" style="border-radius:20px; font-size:12.5px; width:260px;">
        </div>
      </div>

      <div style="overflow-x:auto;">
        <table style="width:100%; border-collapse:collapse; font-size:13px;">
          <thead>
            <tr style="border-bottom:2px solid var(--border); text-align:left; color:var(--text-secondary);">
              <th style="padding:10px;">#</th>
              <th style="padding:10px;">Học Viên & Email</th>
              <th style="padding:10px;">Vai Trò</th>
              <th style="padding:10px; text-align:center;">Trình Độ</th>
              <th style="padding:10px; text-align:center;">Số Dư & Điểm</th>
              <th style="padding:10px; text-align:center;">Streak</th>
              <th style="padding:10px; text-align:center;">Trạng Thái</th>
              <th style="padding:10px; text-align:right;">Thao Tác</th>
            </tr>
          </thead>
          <tbody id="crm-users-table-body">
            ${usersRowsHtml}
          </tbody>
        </table>
      </div>
    </div>
  `;
}

// ── 3. SUB-TAB GIAO DỊCH & VOUCHER (ORDERS) ──────────────────────────────────
async function renderAdminOrdersTab(container) {
  const [txRes, couponRes] = await Promise.all([
    api.admin.transactions(50),
    api.admin.coupons()
  ]);

  const txs = txRes.transactions || [];
  const coupons = couponRes.coupons || [];
  const fmtVnd = (num) => new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(num || 0);

  const txRowsHtml = txs.map((t, idx) => `
    <tr style="border-bottom:1px solid var(--border);">
      <td style="padding:10px; font-weight:800; font-family:monospace; color:var(--accent-primary);">${t.id}</td>
      <td style="padding:10px;">
        <div style="font-weight:800; color:var(--text-primary);">${t.user_name}</div>
        <div style="font-size:11.5px; color:var(--text-secondary);">${t.user_email}</div>
      </td>
      <td style="padding:10px; font-weight:700; color:var(--text-primary);">${t.package_name}</td>
      <td style="padding:10px; color:#10b981; font-weight:900;">${fmtVnd(t.amount_vnd)}</td>
      <td style="padding:10px; font-size:12px; color:var(--text-secondary);">${t.payment_method}</td>
      <td style="padding:10px; text-align:center;">
        <span class="badge ${t.status === 'completed' ? 'badge-green' : 'badge-yellow'}" style="font-weight:800; font-size:11px;">
          ${t.status === 'completed' ? '✅ Hoàn thành' : '⏳ Chờ duyệt'}
        </span>
      </td>
      <td style="padding:10px; font-size:11.5px; color:var(--text-secondary);">${t.created_at}</td>
      <td style="padding:10px; text-align:right;">
        ${t.status !== 'completed' ? `
          <button class="btn btn-sm btn-success" onclick="approveOrder('${t.id}')" style="font-weight:800; padding:4px 10px; font-size:11.5px;">
            ⚡ Phê Duyệt
          </button>
        ` : `<span style="font-size:12px; color:var(--text-secondary);">Đã xử lý</span>`}
      </td>
    </tr>
  `).join('');

  const couponRowsHtml = coupons.map(c => `
    <tr style="border-bottom:1px solid var(--border);">
      <td style="padding:10px; font-weight:900; color:#38bdf8; font-family:monospace; font-size:14px;">${c.code}</td>
      <td style="padding:10px; font-weight:800; color:#10b981;">Giảm ${c.discount_pct}%</td>
      <td style="padding:10px; font-weight:700;">${c.used_count} / ${c.usage_limit}</td>
      <td style="padding:10px;">
        <span class="badge ${c.status === 'active' ? 'badge-green' : 'badge-red'}" style="font-weight:800; font-size:11px;">
          ${c.status === 'active' ? 'Hoạt động' : 'Hết hạn'}
        </span>
      </td>
      <td style="padding:10px; font-size:12px; color:var(--text-secondary);">${c.expires_at}</td>
      <td style="padding:10px; text-align:right;">
        <button class="btn btn-sm btn-danger" onclick="deleteCouponCode('${c.code}')" style="padding:3px 8px; font-size:11px;">
          Xóa
        </button>
      </td>
    </tr>
  `).join('');

  container.innerHTML = `
    <!-- ORDERS & VOUCHERS GRID -->
    <div style="display:grid; grid-template-columns:1.8fr 1.2fr; gap:20px; align-items:start;">
      <!-- TRANSACTIONS LIST -->
      <div class="card" style="padding:22px; background:var(--bg-card); border-radius:16px;">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:16px;">
          <div>
            <div style="font-size:15px; font-weight:900; color:var(--text-primary);">
              💳 LỊCH SỬ ĐƠN HÀNG & GIAO DỊCH THƯƠNG MẠI
            </div>
            <div style="font-size:12px; color:var(--text-secondary);">Danh sách đơn nạp học phí & nâng cấp gói học viên</div>
          </div>
          <button class="btn btn-sm btn-primary" onclick="openManualOrderModal()" style="font-weight:800;">
            ➕ Tạo Đơn Mới
          </button>
        </div>

        <div style="overflow-x:auto;">
          <table style="width:100%; border-collapse:collapse; font-size:12.5px;">
            <thead>
              <tr style="border-bottom:2px solid var(--border); text-align:left; color:var(--text-secondary);">
                <th style="padding:8px;">Mã Đơn</th>
                <th style="padding:8px;">Học Viên</th>
                <th style="padding:8px;">Gói Đăng Ký</th>
                <th style="padding:8px;">Số Tiền</th>
                <th style="padding:8px;">Hình Thức</th>
                <th style="padding:8px; text-align:center;">Trạng Thái</th>
                <th style="padding:8px;">Thời Gian</th>
                <th style="padding:8px; text-align:right;">Thao Tác</th>
              </tr>
            </thead>
            <tbody>
              ${txRowsHtml}
            </tbody>
          </table>
        </div>
      </div>

      <!-- COUPONS & VOUCHERS LIST -->
      <div class="card" style="padding:22px; background:var(--bg-card); border-radius:16px;">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:16px;">
          <div>
            <div style="font-size:15px; font-weight:900; color:var(--text-primary);">
              🏷️ MÃ GIẢM GIÁ (COUPON & VOUCHER)
            </div>
            <div style="font-size:12px; color:var(--text-secondary);">Chương trình khuyến mãi & ưu đãi học viên</div>
          </div>
          <button class="btn btn-sm btn-warning" onclick="openAddCouponModal()" style="font-weight:900;">
            ➕ Tạo Mã
          </button>
        </div>

        <div style="overflow-x:auto;">
          <table style="width:100%; border-collapse:collapse; font-size:12.5px;">
            <thead>
              <tr style="border-bottom:2px solid var(--border); text-align:left; color:var(--text-secondary);">
                <th style="padding:8px;">Mã Code</th>
                <th style="padding:8px;">Mức Giảm</th>
                <th style="padding:8px;">Lượt Dùng</th>
                <th style="padding:8px;">Trạng Thái</th>
                <th style="padding:8px;">Hạn Dùng</th>
                <th style="padding:8px; text-align:right;">Xóa</th>
              </tr>
            </thead>
            <tbody>
              ${couponRowsHtml}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  `;
}

// ── 4. SUB-TAB CMS 13,973+ TỪ VỰNG (VOCABULARY) ──────────────────────────────
async function renderAdminVocabTab(container) {
  const p = {
    page: window.adminState.vocabPage || 1,
    limit: 25,
    q: window.adminState.vocabQuery || '',
    letter: window.adminState.vocabLetter || '',
    level: window.adminState.vocabLevel || ''
  };

  const res = await api.admin.vocabularies(p);
  window.adminState.vocabTotalPages = res.total_pages || 1;

  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
  const lettersBarHtml = alphabet.map(l => `
    <button class="badge ${window.adminState.vocabLetter === l ? 'badge-purple' : ''}" onclick="filterAdminVocabLetter('${l}')" style="cursor:pointer; padding:4px 8px; font-weight:800; font-size:11.5px; border:1px solid var(--border); background:${window.adminState.vocabLetter === l ? '' : 'var(--bg-secondary)'};">
      ${l}
    </button>
  `).join('');

  const vocabRowsHtml = (res.items || []).map((v, idx) => `
    <tr style="border-bottom:1px solid var(--border);">
      <td style="padding:10px; font-weight:800; color:var(--text-primary); font-size:14px;">${v.word}</td>
      <td style="padding:10px; color:#38bdf8; font-family:monospace;">${v.ipa || ''}</td>
      <td style="padding:10px; font-weight:700; color:var(--text-secondary); text-transform:uppercase; font-size:11px;">${v.pos || 'noun'}</td>
      <td style="padding:10px; font-weight:700; color:#10b981;">${v.meaning_vi || ''}</td>
      <td style="padding:10px; font-size:12px; color:var(--text-secondary); max-width:240px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
        ${v.example_sentence || ''}
      </td>
      <td style="padding:10px; text-align:center;">
        <span class="badge badge-purple" style="font-weight:800; font-size:11px;">${v.cefr_level || 'B1'}</span>
      </td>
      <td style="padding:10px; text-align:right;">
        <div style="display:inline-flex; gap:6px;">
          <button class="btn btn-sm btn-ghost" onclick="speakText('${v.word}')" title="Nghe phát âm" style="padding:3px 6px;">🔊</button>
          <button class="btn btn-sm btn-danger" onclick="deleteVocabWord(${v.id}, '${v.word}')" style="padding:3px 6px; font-size:11px;">Xóa</button>
        </div>
      </td>
    </tr>
  `).join('');

  container.innerHTML = `
    <div class="card" style="padding:22px; background:var(--bg-card); border-radius:16px;">
      <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:14px; margin-bottom:16px;">
        <div>
          <div style="font-size:16px; font-weight:900; color:var(--text-primary);">
            📚 KHO DỮ LIỆU TỪ VỰNG CHUẨN QUỐC TẾ (${res.total} Từ Vựng Toàn Nền Tảng)
          </div>
          <div style="font-size:12px; color:var(--text-secondary);">
            Đầy đủ 26 chữ cái A-Z đều đạt $\\ge$ 500 từ chuẩn học thuật kèm phiên âm IPA và ví dụ thực chiến
          </div>
        </div>

        <button class="btn btn-primary" onclick="openAddVocabModal()" style="font-weight:800;">
          ➕ Thêm Từ Vựng Mới
        </button>
      </div>

      <!-- ALPHABET BAR -->
      <div style="display:flex; gap:4px; flex-wrap:wrap; margin-bottom:14px; align-items:center;">
        <span style="font-size:11.5px; font-weight:800; color:var(--text-secondary); margin-right:4px;">Chữ Cái:</span>
        <button class="badge ${!window.adminState.vocabLetter ? 'badge-purple' : ''}" onclick="filterAdminVocabLetter('')" style="cursor:pointer; padding:4px 8px; font-weight:800; font-size:11px; border:1px solid var(--border);">
          Tất Cả
        </button>
        ${lettersBarHtml}
      </div>

      <!-- SEARCH & FILTER BAR -->
      <div style="display:flex; gap:12px; margin-bottom:16px; flex-wrap:wrap;">
        <input type="text" id="admin-vocab-search-box" class="form-control" placeholder="🔍 Tìm kiếm từ tiếng Anh hoặc nghĩa tiếng Việt..." value="${window.adminState.vocabQuery || ''}" onchange="searchAdminVocab(this.value)" style="flex:1; min-width:240px; border-radius:20px; font-size:12.5px;">
        
        <select class="form-control" onchange="filterAdminVocabLevel(this.value)" style="width:140px; border-radius:20px; font-size:12.5px;">
          <option value="">-- Cấp độ CEFR --</option>
          <option value="A1" ${window.adminState.vocabLevel==='A1'?'selected':''}>A1</option>
          <option value="A2" ${window.adminState.vocabLevel==='A2'?'selected':''}>A2</option>
          <option value="B1" ${window.adminState.vocabLevel==='B1'?'selected':''}>B1</option>
          <option value="B2" ${window.adminState.vocabLevel==='B2'?'selected':''}>B2</option>
          <option value="C1" ${window.adminState.vocabLevel==='C1'?'selected':''}>C1</option>
          <option value="C2" ${window.adminState.vocabLevel==='C2'?'selected':''}>C2</option>
        </select>
      </div>

      <!-- TABLE -->
      <div style="overflow-x:auto;">
        <table style="width:100%; border-collapse:collapse; font-size:13px;">
          <thead>
            <tr style="border-bottom:2px solid var(--border); text-align:left; color:var(--text-secondary);">
              <th style="padding:10px;">Từ Vựng</th>
              <th style="padding:10px;">Phiên Âm IPA</th>
              <th style="padding:10px;">Loại Từ</th>
              <th style="padding:10px;">Nghĩa Tiếng Việt</th>
              <th style="padding:10px;">Câu Ví Dụ Minh Họa</th>
              <th style="padding:10px; text-align:center;">Cấp Độ</th>
              <th style="padding:10px; text-align:right;">Thao Tác</th>
            </tr>
          </thead>
          <tbody>
            ${vocabRowsHtml}
          </tbody>
        </table>
      </div>

      <!-- PAGINATION CONTROLS -->
      <div style="display:flex; justify-content:space-between; align-items:center; margin-top:16px; padding-top:12px; border-top:1px solid var(--border);">
        <div style="font-size:12.5px; color:var(--text-secondary);">
          Trang <b>${res.page}</b> / <b>${res.total_pages}</b> (Tổng cộng <b>${res.total}</b> từ)
        </div>
        <div style="display:flex; gap:8px;">
          <button class="btn btn-sm btn-secondary" onclick="changeAdminVocabPage(${res.page - 1})" ${res.page <= 1 ? 'disabled' : ''}>
            ⬅️ Trang Trước
          </button>
          <button class="btn btn-sm btn-secondary" onclick="changeAdminVocabPage(${res.page + 1})" ${res.page >= res.total_pages ? 'disabled' : ''}>
            Trang Sau ➡️
          </button>
        </div>
      </div>
    </div>
  `;
}

// ── 5. SUB-TAB 30 ĐỀ QUIZ & 6 KHẢO THÍ CHUẨN HÓA (EXAMS) ──────────────────────
