// ── 6. SUB-TAB AI PROFILES & SYSTEM CONFIG (AI) ──────────────────────────────
async function renderAdminAiProfilesTab(container) {
  const profileRes = await api.admin.getAIProfiles();
  const profiles = profileRes.profiles || [];
  const activeId = profileRes.active_profile_id;

  const profilesHtml = profiles.map(p => {
    const isAct = p.id === activeId;
    return `
      <div class="card" style="padding:18px; border-radius:14px; border:1.5px solid ${isAct ? '#10b981' : 'var(--border)'}; background:${isAct ? 'rgba(16,185,129,0.06)' : 'var(--bg-card)'}; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px; margin-bottom:12px;">
        <div>
          <div style="display:flex; align-items:center; gap:8px; margin-bottom:4px;">
            <span style="font-size:18px;">🤖</span>
            <span style="font-size:15px; font-weight:900; color:var(--text-primary);">${p.name || 'AI Profile'}</span>
            ${isAct ? `<span class="badge badge-green" style="font-weight:900;">ĐANG KÍCH HOẠT CHÍNH THỨC</span>` : ''}
          </div>
          <div style="font-size:12px; color:var(--text-secondary);">
            Provider: <b>${p.provider}</b> • Model: <b>${p.model}</b> • Temperature: <b>${p.temperature || 0.7}</b>
          </div>
        </div>

        <div style="display:flex; gap:8px;">
          <button class="btn btn-sm btn-ghost" onclick="testAIProfileConnection('${p.provider}', '${p.model}', '${p.api_key||''}')" style="font-weight:700;">
            ⚡ Test API
          </button>
          ${!isAct ? `
            <button class="btn btn-sm btn-success" onclick="activateAiProfileNow('${p.id}')" style="font-weight:800;">
              Kích Hoạt Làm API Chính
            </button>
          ` : ''}
        </div>
      </div>
    `;
  }).join('');

  container.innerHTML = `
    <div class="card" style="padding:22px; background:var(--bg-card); border-radius:16px;">
      <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:14px; margin-bottom:16px;">
        <div>
          <div style="font-size:16px; font-weight:900; color:var(--text-primary);">
            🤖 TRUNG TÂM ĐIỀU KHIỂN AI MULTI-PROFILE & API GATEWAY
          </div>
          <div style="font-size:12px; color:var(--text-secondary);">
            Hỗ trợ chuyển đổi tức thì giữa Google Gemini 2.5/3.0, OpenAI GPT-4o, Anthropic Claude, DeepSeek và Local Ollama
          </div>
        </div>

        <button class="btn btn-primary" onclick="openAddAiProfileModal()" style="font-weight:800;">
          ➕ Thêm Cấu Hình API Mới
        </button>
      </div>

      <div style="margin-bottom:20px;">
        ${profilesHtml}
      </div>

      <div id="ai-test-connection-result" style="display:none; margin-top:14px;"></div>
    </div>
  `;
}

// ── 7. SUB-TAB NHẬT KÝ KIỂM TOÁN & SỨC KHỎE HỆ THỐNG (AUDIT) ──────────────────
async function renderAdminAuditTab(container) {
  const [auditRes, healthRes] = await Promise.all([
    api.admin.auditLogs(30),
    api.admin.systemHealth()
  ]);

  const logs = auditRes.logs || [];

  const logsHtml = logs.map(l => `
    <div style="display:flex; justify-content:space-between; align-items:center; padding:10px 14px; border-bottom:1px solid var(--border); font-size:12.5px;">
      <div>
        <span style="font-weight:800; color:var(--accent-primary);">${l.user_email}</span>
        <span style="color:var(--text-primary); margin-left:8px;">${l.action}</span>
      </div>
      <div style="display:flex; gap:12px; align-items:center;">
        <span style="font-weight:800; color:#38bdf8;">+${l.xp_earned} XP</span>
        <span style="color:var(--text-secondary); font-size:11.5px;">${new Date(l.timestamp).toLocaleString('vi-VN')}</span>
      </div>
    </div>
  `).join('');

  container.innerHTML = `
    <!-- SYSTEM HEALTH -->
    <div class="card" style="padding:22px; background:var(--bg-card); border-radius:16px; margin-bottom:20px;">
      <div style="font-size:16px; font-weight:900; color:var(--text-primary); margin-bottom:14px;">
        🏥 CHẨN ĐOÁN TÌNH TRẠNG MÁY CHỦ & CƠ SỞ DỮ LIỆU
      </div>
      <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(200px, 1fr)); gap:12px;">
        <div style="background:var(--bg-secondary); padding:14px; border-radius:12px;">
          <div style="font-size:11.5px; color:var(--text-secondary);">Trạng Thái Máy Chủ</div>
          <div style="font-size:18px; font-weight:900; color:#10b981; margin-top:4px;">✅ HEALTHY & ONLINE</div>
        </div>
        <div style="background:var(--bg-secondary); padding:14px; border-radius:12px;">
          <div style="font-size:11.5px; color:var(--text-secondary);">Kho Từ Vựng Toàn Cục</div>
          <div style="font-size:18px; font-weight:900; color:#38bdf8; margin-top:4px;">${healthRes.total_vocabularies} Từ Vựng</div>
        </div>
        <div style="background:var(--bg-secondary); padding:14px; border-radius:12px;">
          <div style="font-size:11.5px; color:var(--text-secondary);">Cơ Sở Dữ Liệu</div>
          <div style="font-size:14px; font-weight:800; color:#facc15; margin-top:4px;">${healthRes.database}</div>
        </div>
        <div style="background:var(--bg-secondary); padding:14px; border-radius:12px;">
          <div style="font-size:11.5px; color:var(--text-secondary);">AI Inference Engine</div>
          <div style="font-size:14px; font-weight:800; color:#ec4899; margin-top:4px;">${healthRes.ai_engine_status}</div>
        </div>
      </div>
    </div>

    <!-- AUDIT LOG STREAM -->
    <div class="card" style="padding:22px; background:var(--bg-card); border-radius:16px;">
      <div style="font-size:16px; font-weight:900; color:var(--text-primary); margin-bottom:14px;">
        📜 NHẬT KÝ HOẠT ĐỘNG THỜI GIAN THỰC (REAL-TIME AUDIT STREAM)
      </div>
      <div style="background:var(--bg-secondary); border-radius:12px; overflow:hidden;">
        ${logsHtml || '<div style="padding:20px; text-align:center; color:var(--text-secondary);">Chưa có hoạt động nào được ghi nhận.</div>'}
      </div>
    </div>
  `;
}

