window.openAdjustFundsModal = function(userId, email, currentCoins, currentXp, currentStreak) {
  const modalContainer = document.getElementById('admin-modal-container');
  if (!modalContainer) return;

  modalContainer.innerHTML = `
    <div class="lesson-studio-overlay" style="z-index:99999;">
      <div class="card" style="max-width:480px; width:90%; background:var(--bg-card); border-radius:20px; padding:26px; box-shadow:0 20px 60px rgba(0,0,0,0.5);">
        <div style="font-size:18px; font-weight:900; color:var(--text-primary); margin-bottom:6px;">
          💰 ĐIỀU CHỈNH SỐ DƯ & ĐIỂM HỌC VIÊN
        </div>
        <div style="font-size:12.5px; color:var(--text-secondary); margin-bottom:18px;">
          Học viên: <b style="color:var(--accent-primary);">${email}</b>
        </div>

        <div class="form-group" style="margin-bottom:12px;">
          <label class="form-label">Cộng/Trừ Xu (Coins) [Hiện tại: ${currentCoins}]</label>
          <input type="number" id="adjust-coins-input" class="form-control" placeholder="VD: +500 hoặc -100" value="100">
        </div>

        <div class="form-group" style="margin-bottom:12px;">
          <label class="form-label">Cộng/Trừ Điểm Kinh Nghiệm (XP) [Hiện tại: ${currentXp}]</label>
          <input type="number" id="adjust-xp-input" class="form-control" placeholder="VD: +500" value="250">
        </div>

        <div class="form-group" style="margin-bottom:20px;">
          <label class="form-label">Cộng/Trừ Chuỗi Streak (Ngày) [Hiện tại: ${currentStreak}]</label>
          <input type="number" id="adjust-streak-input" class="form-control" placeholder="VD: +5" value="1">
        </div>

        <div style="display:flex; justify-content:flex-end; gap:10px;">
          <button class="btn btn-ghost" onclick="document.getElementById('admin-modal-container').innerHTML=''">
            Hủy Bỏ
          </button>
          <button class="btn btn-primary" onclick="submitAdjustFunds(${userId})" style="font-weight:800;">
            💾 Lưu Thay Đổi
          </button>
        </div>
      </div>
    </div>
  `;
};

window.submitAdjustFunds = async function(userId) {
  const coins = parseInt(document.getElementById('adjust-coins-input')?.value || '0', 10);
  const xp = parseInt(document.getElementById('adjust-xp-input')?.value || '0', 10);
  const streak = parseInt(document.getElementById('adjust-streak-input')?.value || '0', 10);

  try {
    const res = await api.admin.adjustUserFunds(userId, { coins_delta: coins, xp_delta: xp, streak_delta: streak });
    toast(res.message || 'Đã cập nhật số dư thành công!', 'success');
    document.getElementById('admin-modal-container').innerHTML = '';
    loadAdminSubTab('crm');
  } catch (err) {
    toast('Lỗi cập nhật: ' + err.message, 'error');
  }
};

