window.submitManualOrder = async function() {
  const email = document.getElementById('manual-order-email')?.value || '';
  const name = document.getElementById('manual-order-name')?.value || '';
  const sel = document.getElementById('manual-order-package');
  const pkg = sel?.value || 'Gói VIP 1 Năm';
  const price = sel?.options[sel.selectedIndex]?.dataset.price || 990000;
  const method = document.getElementById('manual-order-payment')?.value || 'Thu phí trực tiếp';

  try {
    const res = await api.admin.createManualTransaction({
      user_email: email,
      user_name: name,
      package_name: pkg,
      amount_vnd: parseInt(price, 10),
      payment_method: method
    });
    toast(res.message || 'Đã tạo đơn hàng thành công!', 'success');
    document.getElementById('admin-modal-container').innerHTML = '';
    loadAdminSubTab('orders');
  } catch (err) {
    toast('Lỗi tạo đơn: ' + err.message, 'error');
  }
};

