window.submitAddVocabulary = async function() {
  const word = document.getElementById('new-vocab-word')?.value || '';
  const ipa = document.getElementById('new-vocab-ipa')?.value || '';
  const pos = document.getElementById('new-vocab-pos')?.value || 'noun';
  const meaning = document.getElementById('new-vocab-meaning')?.value || '';
  const example = document.getElementById('new-vocab-example')?.value || '';
  const lvl = document.getElementById('new-vocab-level')?.value || 'B1';
  const topic = document.getElementById('new-vocab-topic')?.value || 'general';

  if (!word.trim() || !meaning.trim()) return toast('Vui lòng nhập từ vựng và nghĩa tiếng Việt!', 'warning');

  try {
    const res = await api.admin.addVocabulary({
      word: word,
      ipa: ipa,
      pos: pos,
      meaning_vi: meaning,
      example_sentence: example,
      cefr_level: lvl,
      topic: topic
    });
    toast(res.message || 'Đã thêm từ vựng thành công!', 'success');
    document.getElementById('admin-modal-container').innerHTML = '';
    loadAdminSubTab('vocab');
  } catch (err) {
    toast('Lỗi: ' + err.message, 'error');
  }
};

window.deleteVocabWord = async function(vocabId, word) {
  if (!confirm(`Bạn có chắc muốn xóa từ '${word}' khỏi cơ sở dữ liệu?`)) return;
  try {
    const res = await api.admin.deleteVocabulary(vocabId);
    toast(res.message || 'Đã xóa từ vựng.', 'info');
    loadAdminSubTab('vocab');
  } catch (err) {
    toast('Lỗi: ' + err.message, 'error');
  }
};

