window.testAIProfileConnection = async function(provider, model, apiKey) {
  const resEl = document.getElementById('ai-test-connection-result');
  if (resEl) {
    resEl.style.display = 'block';
    resEl.innerHTML = '<div class="loading-dots" style="padding:14px; text-align:center;"><span></span><span></span><span></span><p style="margin-top:6px; font-size:12px;">Đang gửi prompt kiểm tra phản hồi API...</p></div>';
  }

  try {
    const startMs = Date.now();
    const res = await api.admin.testAIConnection({ provider: provider, model: model, api_key: apiKey });
    const latency = Date.now() - startMs;
    if (resEl) {
      resEl.innerHTML = `
        <div class="card" style="padding:14px 18px; border-left:4px solid #10b981; background:rgba(16,185,129,0.08);">
          <div style="font-weight:900; color:#10b981; margin-bottom:4px;">✅ KẾT NỐI API THÀNH CÔNG (Độ trễ: ${latency}ms)</div>
          <div style="font-size:12.5px; color:var(--text-primary);">Phản hồi từ mô hình: <em>"${res.reply || 'AI Model responding accurately.'}"</em></div>
        </div>
      `;
    }
  } catch (err) {
    if (resEl) {
      resEl.innerHTML = `
        <div class="card" style="padding:14px 18px; border-left:4px solid #ef4444; background:rgba(239,68,68,0.08);">
          <div style="font-weight:900; color:#ef4444; margin-bottom:4px;">❌ KẾT NỐI API THẤT BẠI</div>
          <div style="font-size:12px; color:var(--text-secondary);">${err.message}</div>
        </div>
      `;
    }
  }
};

